.section-nav { display: flex; flex-direction: column; gap: var(--g-spacing-2); }
.section-link { display: flex; align-items: center; gap: var(--g-spacing-3); padding: var(--g-spacing-3) var(--g-spacing-4); min-height: 44px; border-radius: var(--g-border-radius-m); color: var(--g-color-text-secondary); text-decoration: none; font-size: 13px; transition: background .15s, color .15s; }
.section-link:hover { color: var(--g-color-text-brand); background: var(--g-color-base-selection-hover); }
.section-link.active { background: var(--g-color-base-selection); color: var(--g-color-text-brand-heavy); font-weight: 550; }
